var t=`0667-red-red`;var n=`world-0667`;var a=`GH`;var s=`western-africa`;var o=4;var r=564;var l={en:`Red Red`,ua:`Ред-ред`};var d={en:`Red Red is a Ghana classic prepared with black-eyed peas, yellow onion, garlic, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Ред-ред, страва кухні країни Гана зі складниками: квасоля чорноочка, жовта цибуля, часник, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Soak the dried beans or peas in plentiful cold water for 480 minutes, then drain and discard the soaking liquid; keep refrigerated in hot conditions.`,ua:`Замочіть сухі бобові у великій кількості холодної води на 480 хвилин, після чого злийте й вилийте воду від замочування; за спеки тримайте в холодильнику.`,t:[`soaking-legumes`],m:480,i:[[`black-eyed-peas`,380,`g`],[`water`,800,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 55 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 55 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:55,i:[[`water`,900,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,190,`g`],[`red-palm-oil`,65,`ml`],[`garlic`,3,`clove`],[`tomato`,350,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 15 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 15 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:15,i:[[`plantain`,480,`g`],[`sunflower-oil`,350,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`ground-cumin`,4,`g`],[`parsley`,15,`g`]]}];var u={slug:t,id:n,country:`GH`,region:s,servings:4,minutes:564,title:l,text:d,steps:g};export{a as country,u as default,n as id,r as minutes,s as region,o as servings,t as slug,g as steps,d as text,l as title};